@PluginDescriptor(
	name = "UIM Utilities",
	description = "Quality of life and safety warnings for ultimate ironman accounts",
	tags = {"jake", "uim", "ultimate ironman", "ironman", "utilities", "warning", "items", "item", "ground",
		"drop", "dropped", "deathpile", "floor", "storage", "cox", "chambers", "xeric", "olm", "raid", "raids", "exit", "leave",
		"looting bag", "loot", "bag", "destroy", "protect", "shop", "sell", "store", "general store"}
)
public class UimUtilitiesPlugin extends Plugin
{
	private static final String ISSUES_URL = "https://github.com/jakevollkommer/uim-utilities/issues";
	private static final String SUPPORT_URL = "https://ko-fi.com/jakevollkommer";

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private GroundItemWarning groundItemWarning;

	@Inject
	private LootingBagProtection lootingBagProtection;

	@Inject
	private SellProtection sellProtection;

	// A plain array, walked rather than streamed: menu entry events fire for every entry of every
	// menu, and an iterator or a capturing lambda per event is allocation for nothing
	private Feature[] features = new Feature[0];

	@Provides
	UimUtilitiesConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(UimUtilitiesConfig.class);
	}

	@Override
	protected void startUp()
	{
		features = new Feature[]
		{
			groundItemWarning,
			lootingBagProtection,
			sellProtection,
		};

		for (Feature feature : features)
		{
			feature.overlays().forEach(overlayManager::add);
		}

		clientThread.invokeLater(() ->
		{
			for (Feature feature : features)
			{
				feature.startUp();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		for (Feature feature : features)
		{
			feature.overlays().forEach(overlayManager::remove);
			feature.shutDown();
		}
		features = new Feature[0];
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		for (Feature feature : features)
		{
			feature.onGameTick();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		for (Feature feature : features)
		{
			feature.onGameStateChanged(event);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		for (Feature feature : features)
		{
			feature.onVarbitChanged(event);
		}
	}

	@Subscribe
	public void onItemSpawned(ItemSpawned event)
	{
		for (Feature feature : features)
		{
			feature.onItemSpawned(event);
		}
	}

	@Subscribe
	public void onItemDespawned(ItemDespawned event)
	{
		for (Feature feature : features)
		{
			feature.onItemDespawned(event);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		for (Feature feature : features)
		{
			feature.onItemContainerChanged(event);
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		for (Feature feature : features)
		{
			feature.onGameObjectSpawned(event);
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		for (Feature feature : features)
		{
			feature.onGameObjectDespawned(event);
		}
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		for (Feature feature : features)
		{
			feature.onMenuEntryAdded(event);
		}
	}

	// The config panel cannot host real buttons, so the Feedback "buttons" are checkboxes that act as
	// buttons: any click of the box, tick or untick, opens the link.
	// This method MUST be named onConfigChanged — EventBus.register throws otherwise.
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!UimUtilitiesConfig.GROUP.equals(event.getGroup()) || event.getNewValue() == null)
		{
			return;
		}

		for (Feature feature : features)
		{
			feature.onConfigChanged(event);
		}

		if (UimUtilitiesConfig.SUGGEST_BUTTON_KEY.equals(event.getKey()))
		{
			LinkBrowser.browse(ISSUES_URL);
			return;
		}

		if (UimUtilitiesConfig.SUPPORT_BUTTON_KEY.equals(event.getKey()))
		{
			LinkBrowser.browse(SUPPORT_URL);
		}
	}
}

package com.uimutilities.cox;

import java.util.HashSet;
import java.util.Set;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;

/**
 * The item ids the player brought into the raid, which is what can be left behind. A raid also fills
 * the floor with the player's own items that were never carried in, mostly loot from what was killed
 * along the way, and warning about those is noise.
 *
 * Nothing is filtered out until the capture succeeds: a missed warning is what loses items.
 */
class CarriedItems
{
	private final Set<Integer> itemIds = new HashSet<>();
	private boolean known;

	/**
	 * @return true once both containers have been read. A container can exist before the server has
	 * filled it, and capturing it empty would make every later drop look like raid loot, so an empty
	 * result is treated as not yet captured.
	 */
	boolean capture(ItemContainer inventory, ItemContainer worn)
	{
		if (inventory == null || worn == null)
		{
			return false;
		}

		itemIds.clear();
		addItemIds(inventory);
		addItemIds(worn);
		known = !itemIds.isEmpty();
		return known;
	}

	boolean areKnown()
	{
		return known;
	}

	int size()
	{
		return itemIds.size();
	}

	boolean includes(int itemId)
	{
		return !known || itemIds.contains(itemId);
	}

	void forget()
	{
		itemIds.clear();
		known = false;
	}

	private void addItemIds(ItemContainer container)
	{
		for (Item item : container.getItems())
		{
			if (item.getId() > 0)
			{
				itemIds.add(item.getId());
			}
		}
	}
}

package com.uimutilities.cox;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Optional;
import java.util.function.Predicate;
import net.runelite.api.coords.WorldPoint;

/**
 * Pairs the two halves of a drop: the item leaving the inventory, and the item landing on the floor
 * beside the player. They belong to the same server tick but arrive in either order, so whichever is
 * seen first waits here a few ticks for the other. Nothing counts until both halves are in, which is
 * what keeps loot that lands next to the player out of the count.
 */
class DropWatcher
{
	private static final int TIMEOUT_TICKS = 3;
	private static final int LANDING_RANGE = 2;

	private final List<WaitingDeparture> departures = new ArrayList<>();
	private final List<WaitingLanding> landings = new ArrayList<>();

	/** @return where the drop landed, once the inventory half is in too. */
	Optional<WorldPoint> itemLanded(int itemId, WorldPoint tile, int distanceFromPlayer, int tick)
	{
		if (distanceFromPlayer > LANDING_RANGE)
		{
			return Optional.empty();
		}

		boolean inventoryHalfWasWaiting = claimFirst(departures, departure -> departure.matches(itemId, tick)).isPresent();
		if (inventoryHalfWasWaiting)
		{
			return Optional.of(tile);
		}

		landings.add(new WaitingLanding(itemId, tile, tick));
		return Optional.empty();
	}

	/** @return where the drop landed, once the floor half is in too. */
	Optional<WorldPoint> itemLeftInventory(int itemId, int tick)
	{
		Optional<WorldPoint> landed = claimFirst(landings, landing -> landing.matches(itemId, tick))
			.map(landing -> landing.tile);
		if (landed.isEmpty())
		{
			departures.add(new WaitingDeparture(itemId, tick));
		}
		return landed;
	}

	void expire(int tick)
	{
		int oldestAllowed = tick - TIMEOUT_TICKS;
		departures.removeIf(departure -> departure.tick < oldestAllowed);
		landings.removeIf(landing -> landing.tick < oldestAllowed);
	}

	void clear()
	{
		departures.clear();
		landings.clear();
	}

	/**
	 * Takes the first half still waiting for its partner, one at a time: two of the same item dropped
	 * in quick succession are two drops, and consuming both halves at once would count only one.
	 */
	private static <T> Optional<T> claimFirst(List<T> waiting, Predicate<T> matches)
	{
		Iterator<T> candidates = waiting.iterator();
		while (candidates.hasNext())
		{
			T candidate = candidates.next();
			if (matches.test(candidate))
			{
				candidates.remove();
				return Optional.of(candidate);
			}
		}
		return Optional.empty();
	}

	private static final class WaitingDeparture
	{
		private final int itemId;
		private final int tick;

		private WaitingDeparture(int itemId, int tick)
		{
			this.itemId = itemId;
			this.tick = tick;
		}

		private boolean matches(int itemId, int tick)
		{
			return this.itemId == itemId && this.tick >= tick - TIMEOUT_TICKS;
		}
	}

	private static final class WaitingLanding
	{
		private final int itemId;
		private final WorldPoint tile;
		private final int tick;

		private WaitingLanding(int itemId, WorldPoint tile, int tick)
		{
			this.itemId = itemId;
			this.tile = tile;
			this.tick = tick;
		}

		private boolean matches(int itemId, int tick)
		{
			return this.itemId == itemId && this.tick >= tick - TIMEOUT_TICKS;
		}
	}
}

package com.uimutilities.cox;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;

/**
 * What the player has dropped in this raid and not picked back up, as a stack count per item id per
 * tile. Tiles are instance template points, so an entry survives the scene reloads between rooms and
 * a room the player has walked away from keeps what it is holding.
 */
class DroppedItems
{
	private final Map<WorldPoint, Map<Integer, Integer>> stacksByTile = new HashMap<>();

	void add(WorldPoint tile, int itemId)
	{
		stacksByTile
			.computeIfAbsent(tile, point -> new HashMap<>())
			.merge(itemId, 1, Integer::sum);
	}

	/** @return true when this was one of the dropped items and is no longer counted. */
	boolean remove(WorldPoint tile, int itemId)
	{
		Map<Integer, Integer> stacks = stacksByTile.get(tile);
		int held = stacks == null ? 0 : stacks.getOrDefault(itemId, 0);
		if (held == 0)
		{
			return false;
		}

		if (held > 1)
		{
			stacks.put(itemId, held - 1);
			return true;
		}

		stacks.remove(itemId);
		if (stacks.isEmpty())
		{
			stacksByTile.remove(tile);
		}
		return true;
	}

	int count()
	{
		return stacksByTile.values().stream()
			.flatMap(stacks -> stacks.values().stream())
			.mapToInt(Integer::intValue)
			.sum();
	}

	boolean isEmpty()
	{
		return stacksByTile.isEmpty();
	}

	void clear()
	{
		stacksByTile.clear();
	}
}

