/**
 * Ultimate ironmen use the floor of the Chambers of Xeric as storage, and the raid destroys
 * everything left on it once they leave. While anything they carried in is still lying there, the
 * way out is labelled with the count and its left-click option is pushed down, so leaving takes a
 * deliberate right-click. The menu entry is never removed: the plugin hub rejects that.
 */
@Slf4j
@Singleton
public class GroundItemWarning implements Feature
{
	// The in-dungeon varbit reads zero for a moment on every scene load, so the raid looks left and
	// re-entered on every room change. Tearing the count down on that would drop a live warning
	// while the items are still on the floor, so the raid is only forgotten once the gate has
	// stayed shut for a few ticks. That, rather than the varbit event, is the one place it happens.
	private static final int TICKS_OUTSIDE_BEFORE_FORGETTING = 5;

	private final Client client;
	private final UimUtilitiesConfig config;
	private final RaidScope raidScope;
	private final CarriedItems carriedItems = new CarriedItems();
	private final InventoryLedger inventoryLedger = new InventoryLedger();
	private final DropWatcher dropWatcher = new DropWatcher();
	private final DroppedItems droppedItems = new DroppedItems();
	private final RaidExits raidExits = new RaidExits();
	private final ExitLabelOverlay overlay;

	// A scene load reports nothing as despawned and reports everything the new scene covers as
	// spawning again, so item events say nothing about drops until the load settles
	private boolean sceneLoading;
	private boolean wasInRaid;
	private int ticksOutsideTheRaid;

	@Inject
	public GroundItemWarning(Client client, UimUtilitiesConfig config)
	{
		this.client = client;
		this.config = config;
		this.raidScope = new RaidScope(client);
		this.overlay = new ExitLabelOverlay(this);
	}

	@Override
	public Collection<Overlay> overlays()
	{
		return List.of(overlay);
	}

	@Override
	public void shutDown()
	{
		forgetTheRaid();
	}

	/** True while the player is in the raid with items they dropped still on its floor. */
	public boolean hasItemsLeftBehind()
	{
		return config.coxWarnGroundItems() && !droppedItems.isEmpty() && raidScope.isInRaidDungeon();
	}

	public int itemsLeftBehind()
	{
		return droppedItems.count();
	}

	public List<TileObject> exits()
	{
		return raidExits.objects();
	}

	@Override
	public void onGameTick()
	{
		sceneLoading = false;
		dropWatcher.expire(client.getTickCount());
		logRaidTransitions();

		if (raidScope.isInRaidDungeon())
		{
			ticksOutsideTheRaid = 0;
			captureWhatCanBeLeftBehind();
			findTheExits();
			return;
		}

		ticksOutsideTheRaid++;
		boolean holdsRaidState = !droppedItems.isEmpty() || !exits().isEmpty() || carriedItems.areKnown();
		if (holdsRaidState && ticksOutsideTheRaid >= TICKS_OUTSIDE_BEFORE_FORGETTING)
		{
			forgetTheRaid();
		}
	}

	@Override
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOADING)
		{
			sceneLoading = true;
			dropWatcher.clear();
			raidExits.sceneUnloaded();
			return;
		}

		boolean leftTheGame = state == GameState.LOGIN_SCREEN || state == GameState.HOPPING;
		if (leftTheGame)
		{
			forgetTheRaid();
		}
	}

	@Override
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV)
		{
			return;
		}

		List<Integer> itemsThatLeft = inventoryLedger.itemsThatLeft(event.getItemContainer());
		if (!isTracking())
		{
			return;
		}

		itemsThatLeft.forEach(this::noticeItemLeftInventory);
	}

	@Override
	public void onItemSpawned(ItemSpawned event)
	{
		if (!isTracking() || event.getItem().getOwnership() != TileItem.OWNERSHIP_SELF)
		{
			return;
		}

		Tile tile = event.getTile();
		int itemId = event.getItem().getId();
		dropWatcher
			.itemLanded(itemId, raidScope.templatePointOf(tile), raidScope.distanceFromPlayer(tile), client.getTickCount())
			.ifPresent(landedAt -> countDrop(itemId, landedAt));
	}

	@Override
	public void onItemDespawned(ItemDespawned event)
	{
		if (!isTracking() || event.getItem().getOwnership() != TileItem.OWNERSHIP_SELF)
		{
			return;
		}

		Tile tile = event.getTile();
		boolean wasCounted = droppedItems.remove(raidScope.templatePointOf(tile), event.getItem().getId());
		if (!wasCounted)
		{
			return;
		}

		// The distance says what happened to it: picked up from under the player's feet, or gone
		// from a room that is no longer loaded, which would be this plugin losing track of it
		log.debug("CoX: dropped item {} is gone, {} tiles from the player",
			event.getItem().getId(), raidScope.distanceFromPlayer(tile));
		logCount();
	}

	@Override
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		if (raidScope.isInRaidDungeon())
		{
			raidExits.objectSpawned(event.getGameObject());
		}
	}

	@Override
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		raidExits.objectDespawned(event.getGameObject());
	}

	@Override
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		MenuEntry entry = event.getMenuEntry();
		if (!RaidExits.isObjectAction(entry.getType()))
		{
			return;
		}

		boolean shouldMakeLeavingDeliberate = config.coxDeprioritizeExit()
			&& hasItemsLeftBehind()
			&& raidExits.isExit(event.getIdentifier());
		if (shouldMakeLeavingDeliberate)
		{
			entry.setDeprioritized(true);
		}
	}

	private boolean isTracking()
	{
		return !sceneLoading && raidScope.isInRaidDungeon();
	}

	private void noticeItemLeftInventory(int itemId)
	{
		if (!carriedItems.includes(itemId))
		{
			log.debug("CoX: item {} left the inventory but was not carried in", itemId);
			return;
		}

		dropWatcher.itemLeftInventory(itemId, client.getTickCount())
			.ifPresent(landedAt -> countDrop(itemId, landedAt));
	}

	private void countDrop(int itemId, WorldPoint tile)
	{
		log.debug("CoX: counted dropped item {} at {}", itemId, tile);
		droppedItems.add(tile, itemId);
		logCount();
	}

	private void captureWhatCanBeLeftBehind()
	{
		if (carriedItems.areKnown())
		{
			return;
		}

		if (!carriedItems.capture(client.getItemContainer(InventoryID.INV), client.getItemContainer(InventoryID.WORN)))
		{
			return;
		}

		// The ledger starts from the same moment, or the first drop of the raid has nothing to be
		// compared against
		inventoryLedger.reset(client.getItemContainer(InventoryID.INV));
		log.debug("CoX: carried in {} item ids", carriedItems.size());
	}

	private void findTheExits()
	{
		int found = raidExits.scanOnce(client.getTopLevelWorldView().getScene());
		boolean worthLogging = found >= 0 && log.isDebugEnabled();
		if (worthLogging)
		{
			// The ids say whether these are really ways out: an id that turns up in every room is
			// one of the guesses matching something else
			log.debug("CoX: {} exit objects in the scene {}", found, exitObjectIds());
		}
	}

	private List<Integer> exitObjectIds()
	{
		return exits().stream()
			.map(TileObject::getId)
			.collect(Collectors.toList());
	}

	private void forgetTheRaid()
	{
		droppedItems.clear();
		carriedItems.forget();
		inventoryLedger.forget();
		dropWatcher.clear();
		raidExits.sceneUnloaded();
		sceneLoading = false;
		ticksOutsideTheRaid = 0;
	}

	private void logRaidTransitions()
	{
		boolean inRaid = raidScope.isInRaidDungeon();
		if (inRaid != wasInRaid)
		{
			wasInRaid = inRaid;
			log.debug("CoX: {} the raid dungeon", inRaid ? "entered" : "left");
		}
	}

	private void logCount()
	{
		if (log.isDebugEnabled())
		{
			log.debug("CoX: {} items left behind", droppedItems.count());
		}
	}
}

package com.uimutilities.cox;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;

/**
 * What the inventory held last time it changed, so that the items which have since left it can be
 * named. Leaving the inventory is half of a drop; the other half is the item landing on the floor.
 */
class InventoryLedger
{
	private final Map<Integer, Integer> quantitiesByItemId = new HashMap<>();

	void reset(ItemContainer inventory)
	{
		quantitiesByItemId.clear();
		quantitiesByItemId.putAll(quantitiesOf(inventory));
	}

	/** @return the ids that have less in the inventory than they did, the ledger moving on to now. */
	List<Integer> itemsThatLeft(ItemContainer inventory)
	{
		Map<Integer, Integer> current = quantitiesOf(inventory);
		List<Integer> departed = new ArrayList<>();
		quantitiesByItemId.forEach((itemId, quantity) ->
		{
			if (current.getOrDefault(itemId, 0) < quantity)
			{
				departed.add(itemId);
			}
		});

		quantitiesByItemId.clear();
		quantitiesByItemId.putAll(current);
		return departed;
	}

	void forget()
	{
		quantitiesByItemId.clear();
	}

	private static Map<Integer, Integer> quantitiesOf(ItemContainer container)
	{
		Map<Integer, Integer> quantities = new HashMap<>();
		if (container == null)
		{
			return quantities;
		}

		for (Item item : container.getItems())
		{
			if (item.getId() > 0)
			{
				quantities.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return quantities;
	}
}

package com.uimutilities.cox;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import net.runelite.api.GameObject;
import net.runelite.api.MenuAction;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.gameval.ObjectID;

/**
 * The ways out of the raid: the objects the exit label is drawn on, and the ids the deprioritize
 * matches. Only RAIDS_EXIT_STEPS_MULTI has been seen in a raid, as the steps out of the first room;
 * the rest are candidates from the gameval constants and are still to be confirmed.
 */
class RaidExits
{
	// gameval's ObjectID1 is package-private, so the two ids it holds are named here instead
	private static final int RAIDS_EXIT_STEPS_MULTI = 49999;
	private static final int RAIDS_EXIT_STEPS_RELOAD = 50000;

	private static final Set<Integer> EXIT_OBJECT_IDS = Set.of(
		RAIDS_EXIT_STEPS_MULTI,
		RAIDS_EXIT_STEPS_RELOAD,
		ObjectID.RAIDS_BOSSEXIT,
		ObjectID.RAIDS_EXIT_STEPS
	);

	private final List<TileObject> exits = new ArrayList<>();

	// Objects spawn while the scene is still loading, before the in-dungeon varbit says the raid is
	// what loaded, so those spawns are missed and the scene is read back for exits instead
	private boolean scanned;

	boolean isExit(int objectId)
	{
		return EXIT_OBJECT_IDS.contains(objectId);
	}

	List<TileObject> objects()
	{
		return exits;
	}

	/** Catches an exit that appears mid-raid, such as the one out of the Olm chamber. */
	void objectSpawned(GameObject object)
	{
		remember(object);
	}

	void objectDespawned(GameObject object)
	{
		exits.remove(object);
	}

	void sceneUnloaded()
	{
		exits.clear();
		scanned = false;
	}

	/** @return the number of exits found, or -1 when the scene has already been read. */
	int scanOnce(Scene scene)
	{
		if (scanned)
		{
			return -1;
		}

		scanned = true;
		for (Tile[][] plane : scene.getTiles())
		{
			for (Tile[] column : plane)
			{
				for (Tile tile : column)
				{
					rememberExitsOn(tile);
				}
			}
		}
		return exits.size();
	}

	static boolean isObjectAction(MenuAction action)
	{
		switch (action)
		{
			case GAME_OBJECT_FIRST_OPTION:
			case GAME_OBJECT_SECOND_OPTION:
			case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION:
			case GAME_OBJECT_FIFTH_OPTION:
				return true;
			default:
				return false;
		}
	}

	private void rememberExitsOn(Tile tile)
	{
		GameObject[] objects = tile == null ? null : tile.getGameObjects();
		if (objects == null)
		{
			return;
		}

		for (GameObject object : objects)
		{
			remember(object);
		}
	}

	private void remember(GameObject object)
	{
		// A multi-tile object is listed on every tile it covers, and the scan runs over objects the
		// spawn events have already reported
		boolean isNewExit = object != null && isExit(object.getId()) && !exits.contains(object);
		if (isNewExit)
		{
			exits.add(object);
		}
	}
}

package com.uimutilities.cox;

import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarbitID;

/**
 * Where and when the raid counts.
 *
 * Object and item ids repeat across unrelated content and must never be matched globally, so
 * everything in this package is gated on RAIDS_CLIENT_INDUNGEON. The varbit belongs to the Chambers
 * of Xeric alone, which scopes the ids more tightly than a list of the raid's regions would: the
 * raid is laid out across more regions than any hardcoded list is likely to hold, and a room in a
 * region missing from it would turn the whole feature off without a word.
 */
class RaidScope
{
	private final Client client;

	RaidScope(Client client)
	{
		this.client = client;
	}

	boolean isInRaidDungeon()
	{
		return client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 1;
	}

	/**
	 * The instance template point of a tile, which survives the scene reloads between rooms.
	 * Instance world coordinates do not: the chunks are remapped on every load.
	 */
	WorldPoint templatePointOf(Tile tile)
	{
		return WorldPoint.fromLocalInstance(client, tile.getLocalLocation(), tile.getPlane());
	}

	/** @return tiles between the player and this tile, or {@link Integer#MAX_VALUE} with no player. */
	int distanceFromPlayer(Tile tile)
	{
		Player player = client.getLocalPlayer();
		WorldPoint playerAt = player == null ? null : player.getWorldLocation();
		return playerAt == null ? Integer.MAX_VALUE : playerAt.distanceTo(tile.getWorldLocation());
	}
}

package com.uimutilities.lootingbag;

import com.uimutilities.Feature;
import com.uimutilities.UimUtilitiesConfig;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.ItemID;

/**
 * Destroying a looting bag outside the Wilderness takes everything inside it with it, which for an
 * ultimate ironman is the whole point of carrying one. The Destroy option comes off the bag while
 * the setting is on, so there is nothing to misclick, and turning the setting off gives it back.
 */
@Singleton
public class LootingBagProtection implements Feature
{
	private static final String DESTROY = "Destroy";

	private static final Set<Integer> LOOTING_BAG_IDS = Set.of(
		ItemID.LOOTING_BAG,
		ItemID.LOOTING_BAG_OPEN
	);

	private final Client client;
	private final UimUtilitiesConfig config;

	@Inject
	public LootingBagProtection(Client client, UimUtilitiesConfig config)
	{
		this.client = client;
		this.config = config;
	}

	@Override
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		// Most menu entries carry no item at all, so the id is the cheap way out of this
		boolean isLootingBagEntry = LOOTING_BAG_IDS.contains(event.getItemId());
		if (!isLootingBagEntry || !DESTROY.equals(event.getOption()) || !config.hideLootingBagDestroy())
		{
			return;
		}

		client.getMenu().removeMenuEntry(event.getMenuEntry());
	}
}

package com.uimutilities.shops;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.client.util.Text;
import net.runelite.client.util.WildcardMatcher;

/**
 * The item names the player has asked to protect, in the shape of the Ground Items lists: comma
 * separated, with * wildcards.
 *
 * A plain name also covers that item's variants, which carry the base name plus a suffix, so one
 * entry protects a trident of the seas full or empty and a barrows piece at any degradation.
 */
class ProtectedItemList
{
	// Names are matched far more often than the list changes, so exact entries answer from a set and
	// only wildcards are walked
	private final Set<String> names = new HashSet<>();
	private final List<String> patterns = new ArrayList<>();

	void replaceWith(String commaSeparatedNames)
	{
		names.clear();
		patterns.clear();

		for (String entry : Text.fromCSV(commaSeparatedNames))
		{
			if (entry.contains("*"))
			{
				patterns.add(entry);
				continue;
			}

			names.add(entry.toLowerCase());
		}
	}

	boolean covers(String itemName)
	{
		String name = itemName.toLowerCase();
		if (names.contains(name) || names.contains(withoutVariantSuffix(name)))
		{
			return true;
		}

		return patterns.stream().anyMatch(pattern -> WildcardMatcher.matches(pattern, itemName));
	}

	/**
	 * Strips what marks a name as a variant of an item: a trailing bracket for charges and ornament
	 * kits (Trident of the seas (full), Dragon dagger(p++)) and a trailing number for the degraded
	 * barrows pieces (Ahrim's robetop 75).
	 */
	private static String withoutVariantSuffix(String name)
	{
		if (name.endsWith(")"))
		{
			int bracket = name.lastIndexOf('(');
			return bracket <= 0 ? name : name.substring(0, bracket).trim();
		}

		int lastSpace = name.lastIndexOf(' ');
		boolean endsWithNumber = lastSpace > 0
			&& lastSpace < name.length() - 1
			&& name.substring(lastSpace + 1).chars().allMatch(Character::isDigit);
		return endsWithNumber ? name.substring(0, lastSpace) : name;
	}
}

package com.uimutilities.shops;

import com.uimutilities.Feature;
import com.uimutilities.UimUtilitiesConfig;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.util.Text;

/**
 * A general store will happily buy a twisted bow, and the item is gone the moment the shop closes.
 * Sell options are taken off the items on the protected list, so selling one means editing the list
 * first.
 */
@Singleton
public class SellProtection implements Feature
{
	private static final String SELL = "Sell";

	private final Client client;
	private final UimUtilitiesConfig config;
	private final ProtectedItemList protectedItems = new ProtectedItemList();

	@Inject
	public SellProtection(Client client, UimUtilitiesConfig config)
	{
		this.client = client;
		this.config = config;
	}

	@Override
	public void startUp()
	{
		protectedItems.replaceWith(config.protectedItems());
	}

	@Override
	public void onConfigChanged(ConfigChanged event)
	{
		if (UimUtilitiesConfig.PROTECTED_ITEMS_KEY.equals(event.getKey()))
		{
			protectedItems.replaceWith(config.protectedItems());
		}
	}

	@Override
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		// Most menu entries carry no item at all, so the id is the cheap way out of this
		boolean isSellEntry = event.getItemId() > 0 && event.getOption().startsWith(SELL);
		if (!isSellEntry || !config.blockSelling())
		{
			return;
		}

		if (protectedItems.covers(Text.removeTags(event.getTarget())))
		{
			client.getMenu().removeMenuEntry(event.getMenuEntry());
		}
	}
}

